CREATE OR REPLACE FUNCTION public.adjust_shells_from_rating()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  delta integer := 0;
  sid uuid;
begin
  if tg_op = 'INSERT' then
    sid := new.student_id;
    if new.rating = 'good' then delta := 1; end if;
  elsif tg_op = 'UPDATE' then
    sid := new.student_id;
    if old.rating <> 'good' and new.rating = 'good' then delta := 1; end if;
    if old.rating = 'good' and new.rating <> 'good' then delta := -1; end if;
  elsif tg_op = 'DELETE' then
    sid := old.student_id;
    if old.rating = 'good' then delta := -1; end if;
  end if;

  if delta <> 0 then
    insert into public.student_progress(student_id, shells)
    values (sid, greatest(0, delta))
    on conflict (student_id)
    do update set shells = greatest(0, public.student_progress.shells + delta),
                  updated_at = now();
  end if;

  return coalesce(new, old);
end;
$function$

CREATE OR REPLACE FUNCTION public.rls_auto_enable()
 RETURNS event_trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  cmd record;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        EXECUTE format('alter table if exists %s enable row level security', cmd.object_identity);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION public.create_child_access_code(p_student_id uuid, p_valid_days integer DEFAULT 365)
 RETURNS TABLE(qr_token text, pin text, expires_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_token text;
  v_pin text;
  v_pin_bytes bytea;
  v_expires timestamptz;
  v_days integer;
begin
  if auth.uid() is null then
    raise exception 'Keine Anmeldung vorhanden';
  end if;

  if coalesce((auth.jwt()->>'is_anonymous')::boolean, false) = true then
    raise exception 'Nur Lehrkräfte dürfen QR-Zugänge erzeugen';
  end if;

  if not public.is_teacher_of_student(p_student_id) then
    raise exception 'Keine Berechtigung für dieses Kind';
  end if;

  v_days := greatest(1, least(coalesce(p_valid_days, 365), 3650));
  v_token := encode(extensions.gen_random_bytes(32), 'hex');
  v_pin_bytes := extensions.gen_random_bytes(4);

  v_pin := (
    100000 + (
      (
        get_byte(v_pin_bytes,0)::bigint * 16777216 +
        get_byte(v_pin_bytes,1)::bigint * 65536 +
        get_byte(v_pin_bytes,2)::bigint * 256 +
        get_byte(v_pin_bytes,3)::bigint
      ) % 900000
    )
  )::text;

  v_expires := now() + make_interval(days => v_days);

  update public.child_access_codes
  set active = false
  where student_id = p_student_id
    and active = true;

  insert into public.child_access_codes(
    student_id, token_hash, pin_hash, active, expires_at
  )
  values (
    p_student_id,
    encode(extensions.digest(v_token, 'sha256'), 'hex'),
    extensions.crypt(v_pin, extensions.gen_salt('bf', 10)),
    true,
    v_expires
  );

  return query select v_token, v_pin, v_expires;
end;
$function$

CREATE OR REPLACE FUNCTION public.add_school_member(p_school_id uuid, p_email text, p_role text DEFAULT 'teacher'::text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_user uuid; v_name text; v_role text;
begin
  if not exists(
    select 1 from public.school_members
    where school_id=p_school_id and user_id=auth.uid() and role='admin'
  ) then raise exception 'Keine Berechtigung'; end if;

  v_role:=case when p_role='admin' then 'admin' else 'teacher' end;

  select u.id,coalesce(p.display_name,u.email)
  into v_user,v_name
  from auth.users u
  left join public.profiles p on p.id=u.id
  where lower(u.email)=lower(btrim(p_email))
    and coalesce(p.role,'')='teacher'
  limit 1;

  if v_user is null then raise exception 'Lehrkraft nicht gefunden'; end if;

  insert into public.school_members(school_id,user_id,role)
  values(p_school_id,v_user,v_role)
  on conflict(school_id,user_id) do update set role=excluded.role;

  return v_name;
end;
$function$

CREATE OR REPLACE FUNCTION public.create_school(p_name text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_id uuid;
begin
  if auth.uid() is null or not public.is_teacher_role() then
    raise exception 'Nur Lehrkräfte';
  end if;
  if btrim(coalesce(p_name,''))='' then raise exception 'Name fehlt'; end if;

  insert into public.schools(name,created_by)
  values(btrim(p_name),auth.uid())
  returning id into v_id;

  insert into public.school_members(school_id,user_id,role)
  values(v_id,auth.uid(),'admin');

  insert into public.school_settings(school_id)
  values(v_id)
  on conflict(school_id) do nothing;

  return v_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.redeem_child_access(p_qr_token text, p_pin text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_student_id uuid;
  v_student_name text;
begin
  if auth.uid() is null then
    raise exception 'Keine Anmeldung vorhanden';
  end if;

  if coalesce((auth.jwt()->>'is_anonymous')::boolean, false) = false then
    raise exception 'Dieser Zugang ist nur für Kindergeräte vorgesehen';
  end if;

  select c.student_id, s.display_name
  into v_student_id, v_student_name
  from public.child_access_codes c
  join public.students s on s.id = c.student_id
  where c.active = true
    and c.token_hash = encode(extensions.digest(p_qr_token, 'sha256'), 'hex')
    and c.pin_hash = extensions.crypt(p_pin, c.pin_hash)
    and (c.expires_at is null or c.expires_at > now())
  limit 1;

  if v_student_id is null then
    raise exception 'QR-Code oder PIN ist ungültig';
  end if;

  insert into public.student_device_links(user_id, student_id, linked_at)
  values (auth.uid(), v_student_id, now())
  on conflict (user_id)
  do update set
    student_id = excluded.student_id,
    linked_at = now();

  update public.profiles
  set role = 'student',
      display_name = v_student_name
  where id = auth.uid();

  return v_student_id;
end;
$function$

