CREATE OR REPLACE FUNCTION public.create_class_child_access_codes_qr(p_class_id uuid, p_valid_days integer DEFAULT 365)
 RETURNS TABLE(student_id uuid, display_name text, qr_token text, expires_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  r record;
  v_token text;
  v_dummy_pin text;
  v_pin_bytes bytea;
  v_expires timestamptz;
  v_days integer;
begin
  if auth.uid() is null then
    raise exception 'Keine Anmeldung vorhanden';
  end if;

  if coalesce((auth.jwt()->>'is_anonymous')::boolean, false) = true then
    raise exception 'Nur Lehrkräfte dürfen QR-Zugänge erzeugen';
  end if;

  if not public.is_teacher_of_class(p_class_id) then
    raise exception 'Keine Berechtigung für diese Klasse';
  end if;

  v_days := greatest(1, least(coalesce(p_valid_days, 365), 3650));

  for r in
    select s.id, s.display_name
    from public.students s
    where s.class_id = p_class_id
    order by s.display_name
  loop
    v_token := encode(extensions.gen_random_bytes(32), 'hex');
    v_pin_bytes := extensions.gen_random_bytes(4);
    v_dummy_pin := (
      100000 + (
        (
          get_byte(v_pin_bytes,0)::bigint * 16777216 +
          get_byte(v_pin_bytes,1)::bigint * 65536 +
          get_byte(v_pin_bytes,2)::bigint * 256 +
          get_byte(v_pin_bytes,3)::bigint
        ) % 900000
      )
    )::text;
    v_expires := now() + make_interval(days => v_days);

    update public.child_access_codes
    set active = false
    where child_access_codes.student_id = r.id
      and active = true;

    insert into public.child_access_codes(
      student_id, token_hash, pin_hash, active, expires_at
    )
    values (
      r.id,
      encode(extensions.digest(v_token, 'sha256'), 'hex'),
      extensions.crypt(v_dummy_pin, extensions.gen_salt('bf', 10)),
      true,
      v_expires
    );

    student_id := r.id;
    display_name := r.display_name;
    qr_token := v_token;
    expires_at := v_expires;
    return next;
  end loop;
end;
$function$

