CREATE OR REPLACE FUNCTION public.create_student_for_class(p_class_id uuid, p_display_name text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_name text;
  v_student_id uuid;
begin
  if auth.uid() is null then
    raise exception 'Keine Anmeldung vorhanden';
  end if;

  if coalesce((auth.jwt()->>'is_anonymous')::boolean, false) = true then
    raise exception 'Nur Lehrkräfte dürfen Kinder anlegen';
  end if;

  if not public.is_teacher_of_class(p_class_id) then
    raise exception 'Keine Berechtigung für diese Klasse';
  end if;

  v_name := btrim(coalesce(p_display_name, ''));
  if char_length(v_name) < 1 then
    raise exception 'Name fehlt';
