CREATE OR REPLACE FUNCTION public.remove_school_member(p_school_id uuid, p_user_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if not public.is_school_admin(p_school_id) then
    raise exception 'Keine Berechtigung';
  end if;
  if p_user_id=auth.uid() then
    raise exception 'Eigenes Admin-Konto kann hier nicht entfernt werden';
  end if;

  delete from public.class_teacher_links ctl
  using public.classes c
  where ctl.class_id=c.id
    and c.school_id=p_school_id
    and ctl.user_id=p_user_id;

  delete from public.school_members
  where school_id=p_school_id and user_id=p_user_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.activate_teacher_account(p_user_id uuid, p_school_id uuid, p_display_name text, p_role text DEFAULT 'teacher'::text, p_class_ids uuid[] DEFAULT '{}'::uuid[])
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_class uuid;
  v_role text;
begin
  if not public.is_school_admin(p_school_id) then
    raise exception 'Keine Berechtigung';
  end if;

  v_role:=case when p_role='admin' then 'admin' else 'teacher' end;

  update public.profiles
  set role='teacher',
      display_name=coalesce(nullif(btrim(p_display_name),''),display_name),
      must_change_password=true
  where id=p_user_id;

  if not found then
    raise exception 'Benutzerprofil fehlt';
  end if;

  insert into public.school_members(school_id,user_id,role)
  values(p_school_id,p_user_id,v_role)
  on conflict(school_id,user_id)
  do update set role=excluded.role;

  foreach v_class in array coalesce(p_class_ids,'{}'::uuid[]) loop
    if exists(
      select 1 from public.classes c
      where c.id=v_class and c.school_id=p_school_id
    ) then
      insert into public.class_teacher_links(class_id,user_id)
      values(v_class,p_user_id)
      on conflict do nothing;
    end if;
  end loop;
end;
$function$

CREATE OR REPLACE FUNCTION public.create_student_for_class(p_class_id uuid, p_display_name text, p_avatar_emoji text DEFAULT '🦦'::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_name text;
  v_student_id uuid;
  v_order integer;
begin
  if auth.uid() is null or coalesce((auth.jwt()->>'is_anonymous')::boolean,false) then
    raise exception 'Nur Lehrkräfte dürfen Kinder anlegen';
  end if;
  if not public.is_teacher_of_class(p_class_id) then
    raise exception 'Keine Berechtigung für diese Klasse';
  end if;
  v_name:=btrim(coalesce(p_display_name,''));
  if char_length(v_name)<1 or char_length(v_name)>60 then
    raise exception 'Ungültiger Name';
  end if;
  select coalesce(max(sort_order),0)+10 into v_order
  from public.students where class_id=p_class_id;
  insert into public.students(class_id,display_name,avatar_emoji,sort_order)
  values(p_class_id,v_name,coalesce(nullif(btrim(p_avatar_emoji),''),'🦦'),v_order)
  returning id into v_student_id;
  return v_student_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.apply_goal_to_students(p_student_ids uuid[], p_week_start date, p_goal text, p_help_text text DEFAULT ''::text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_id uuid;
  v_count integer:=0;
begin
  if auth.uid() is null or coalesce((auth.jwt()->>'is_anonymous')::boolean,false) then
    raise exception 'Nur Lehrkräfte';
  end if;
  if btrim(coalesce(p_goal,''))='' then
    raise exception 'Ziel fehlt';
  end if;
  foreach v_id in array p_student_ids loop
    if not public.is_teacher_of_student(v_id) then
      raise exception 'Keine Berechtigung';
    end if;
    insert into public.weekly_plans(student_id,week_start,goal,help_text,checkin_completed)
