CREATE OR REPLACE FUNCTION public.carry_forward_weekly_goals(p_class_id uuid, p_week_start date)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  r record;
  prev record;
  v_count integer:=0;
begin
  if not public.is_teacher_of_class(p_class_id) then
    raise exception 'Keine Berechtigung';
  end if;

  for r in
    select id from public.students
    where class_id=p_class_id and archived_at is null
  loop
    if not exists(
      select 1 from public.weekly_plans
      where student_id=r.id and week_start=p_week_start
    ) then
      select goal,help_text,checkout_decision
      into prev
      from public.weekly_plans
      where student_id=r.id and week_start<p_week_start
      order by week_start desc limit 1;

      if prev.goal is not null
         and coalesce(prev.checkout_decision,'continue')='continue' then
        insert into public.weekly_plans(
          student_id,week_start,goal,help_text,checkin_completed
        )
        values(
          r.id,p_week_start,prev.goal,coalesce(prev.help_text,''),false
        );
        v_count:=v_count+1;
      end if;
    end if;
  end loop;

  return v_count;
end;
