CREATE OR REPLACE FUNCTION public.configure_teacher_account(p_user_id uuid, p_school_id uuid, p_display_name text, p_role text DEFAULT 'teacher'::text, p_class_ids uuid[] DEFAULT '{}'::uuid[], p_grade_levels smallint[] DEFAULT '{}'::smallint[], p_must_change_password boolean DEFAULT true)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_class uuid;
  v_grade smallint;
  v_role text;
begin
  if not public.is_school_admin(p_school_id) then
    raise exception 'Keine Berechtigung';
  end if;

  v_role:=case when p_role='admin' then 'admin' else 'teacher' end;

  insert into public.profiles(id,role,display_name,must_change_password)
  values(
    p_user_id,
    'teacher',
    coalesce(nullif(btrim(p_display_name),''),'Lehrkraft'),
    coalesce(p_must_change_password,false)
  )
  on conflict(id)
  do update set
    role='teacher',
    display_name=excluded.display_name,
    must_change_password=case
      when excluded.must_change_password then true
      else public.profiles.must_change_password
    end;

  insert into public.school_members(school_id,user_id,role)
  values(p_school_id,p_user_id,v_role)
  on conflict(school_id,user_id)
  do update set role=excluded.role;

  delete from public.class_teacher_links ctl
  using public.classes c
  where ctl.class_id=c.id
    and c.school_id=p_school_id
    and ctl.user_id=p_user_id;

  foreach v_class in array coalesce(p_class_ids,'{}'::uuid[]) loop
    if exists(
      select 1 from public.classes c
      where c.id=v_class
        and c.school_id=p_school_id
        and c.archived_at is null
    ) then
      insert into public.class_teacher_links(class_id,user_id)
      values(v_class,p_user_id)
      on conflict do nothing;
    end if;
  end loop;

  delete from public.grade_teacher_links
  where school_id=p_school_id
    and user_id=p_user_id;

  foreach v_grade in array coalesce(p_grade_levels,'{}'::smallint[]) loop
    if v_grade between 1 and 4 then
      insert into public.grade_teacher_links(school_id,grade_level,user_id)
      values(p_school_id,v_grade,p_user_id)
      on conflict do nothing;
    end if;
  end loop;
end;
$function$

CREATE OR REPLACE FUNCTION public.grade_save_rating(p_student_id uuid, p_week_start date, p_weekday smallint, p_lesson_no smallint, p_rating text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_school uuid;
  v_grade smallint;
begin
  select c.school_id,c.grade_level
    into v_school,v_grade
  from public.students s
  join public.classes c on c.id=s.class_id
  where s.id=p_student_id
    and s.archived_at is null
    and c.archived_at is null;

  if v_school is null
     or v_grade is null
     or not public.has_grade_access(v_school,v_grade) then
    raise exception 'Keine Berechtigung für diese Stufe';
  end if;

  if p_weekday not between 1 and 5
     or p_lesson_no not between 1 and 8
     or p_rating not in ('good','partial','difficult') then
    raise exception 'Ungültige Bewertung';
  end if;

  if not exists(
    select 1 from public.weekly_plans wp
    where wp.student_id=p_student_id
      and wp.week_start=p_week_start
  ) then
    raise exception 'Für dieses Kind gibt es in dieser Woche noch keinen Plan';
  end if;

  if exists(
    select 1
    from public.student_schedule_slots ss
    where ss.student_id=p_student_id
      and ss.weekday=p_weekday
      and ss.lesson_no=p_lesson_no
      and ss.enabled=false
  ) then
    raise exception 'Diese Stunde ist für das Kind deaktiviert';
  end if;

  insert into public.ratings(
    student_id,week_start,weekday,lesson_no,rating,updated_by,updated_at
  )
  values(
    p_student_id,p_week_start,p_weekday,p_lesson_no,p_rating,auth.uid(),now()
  )
  on conflict(student_id,week_start,weekday,lesson_no)
  do update set
    rating=excluded.rating,
    updated_by=auth.uid(),
    updated_at=now();
end;
$function$

CREATE OR REPLACE FUNCTION public.get_teacher_permissions(p_school_id uuid, p_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_role text;
  v_name text;
  v_classes jsonb;
  v_grades jsonb;
begin
  if not public.is_school_admin(p_school_id) then
    raise exception 'Keine Berechtigung';
  end if;

  select sm.role,coalesce(nullif(p.display_name,''),'Lehrkraft')
    into v_role,v_name
  from public.school_members sm
  left join public.profiles p on p.id=sm.user_id
  where sm.school_id=p_school_id
    and sm.user_id=p_user_id;

  if v_role is null then
    raise exception 'Lehrkraft nicht gefunden';
  end if;

  select coalesce(jsonb_agg(ctl.class_id order by ctl.class_id),'[]'::jsonb)
    into v_classes
  from public.class_teacher_links ctl
  join public.classes c on c.id=ctl.class_id
  where ctl.user_id=p_user_id
    and c.school_id=p_school_id
    and c.archived_at is null;

  select coalesce(jsonb_agg(gtl.grade_level order by gtl.grade_level),'[]'::jsonb)
    into v_grades
  from public.grade_teacher_links gtl
  where gtl.user_id=p_user_id
    and gtl.school_id=p_school_id;

  return jsonb_build_object(
    'user_id',p_user_id,
    'display_name',v_name,
    'role',v_role,
    'class_ids',v_classes,
    'grade_levels',v_grades
  );
end;
$function$

