 if v_new is not null then return v_new; end if;
 if v_old.archived_at is not null then raise exception 'Die Ausgangsklasse ist bereits archiviert'; end if;
 if length(btrim(coalesce(p_new_name,''))) not between 1 and 80 or p_new_school_year !~ '^20[0-9]{2}/[0-9]{2}$' or p_new_grade not between 1 and 4 then raise exception 'Ungültige Angaben zum neuen Schuljahr'; end if;
 select count(*) into v_invalid from (select distinct unnest(coalesce(p_student_ids,array[]::uuid[])) sid) i left join public.students s on s.id=i.sid and s.class_id=p_class_id and s.archived_at is null where s.id is null;
 if v_invalid>0 then raise exception 'Ungültige Kinderauswahl'; end if;
 insert into public.classes(name,teacher_id,school_id,grade_level,school_year) values(btrim(p_new_name),v_old.teacher_id,v_old.school_id,p_new_grade,p_new_school_year) returning id into v_new;
 insert into public.class_teacher_links(class_id,user_id,role) select v_new,user_id,role from public.class_teacher_links where class_id=p_class_id on conflict do nothing;
 insert into public.students(class_id,display_name,avatar_emoji,sort_order,is_demo) select v_new,display_name,avatar_emoji,sort_order,is_demo from public.students where class_id=p_class_id and archived_at is null and id=any(coalesce(p_student_ids,array[]::uuid[]));
 update public.students set archived_at=now() where class_id=p_class_id and archived_at is null;
 update public.classes set archived_at=now() where id=p_class_id;
 insert into public.class_year_transitions(source_class_id,target_class_id,created_by) values(p_class_id,v_new,auth.uid());
 return v_new;
end $function$

CREATE OR REPLACE FUNCTION public.list_school_year_source_students(p_class_id uuid)
 RETURNS TABLE(student_id uuid, display_name text, avatar_emoji text, school_year text, grade_level smallint)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_school uuid;
begin
 if auth.uid() is null or coalesce((auth.jwt()->>'is_anonymous')::boolean,false) then raise exception 'Nur Schuladmins'; end if;
 select c.school_id into v_school from public.classes c where c.id=p_class_id and c.archived_at is null;
 if v_school is null or not public.is_school_admin(v_school) then raise exception 'Keine Berechtigung'; end if;
 return query select s.id,s.display_name,s.avatar_emoji,c.school_year,c.grade_level from public.students s join public.classes c on c.id=s.class_id where s.class_id=p_class_id and s.archived_at is null order by s.sort_order,s.display_name;
end $function$

CREATE OR REPLACE FUNCTION public.set_weekly_goal_icon(p_student_id uuid, p_week_start date, p_icon text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 if auth.uid() is null or coalesce((auth.jwt()->>'is_anonymous')::boolean,false) or not public.can_teacher_access_student(p_student_id) then raise exception 'Keine Berechtigung'; end if;
 if p_icon not in ('target','ear','hand','clock','peace') then raise exception 'Ungültiges Symbol'; end if;
