CREATE OR REPLACE FUNCTION public.grade_save_checkin(p_student_id uuid, p_week_start date, p_goal text, p_help_text text, p_feeling text, p_icon text, p_weekly_shell_target integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_school uuid;
  v_grade smallint;
begin
  select c.school_id,c.grade_level
    into v_school,v_grade
  from public.students s
  join public.classes c on c.id=s.class_id
  where s.id=p_student_id
    and s.archived_at is null
    and c.archived_at is null;

  if auth.uid() is null
     or v_school is null
     or v_grade is null
     or not public.has_grade_access(v_school,v_grade) then
    raise exception 'Keine Berechtigung für diese Stufe';
  end if;

  if btrim(coalesce(p_goal,''))='' then
    raise exception 'Ziel fehlt';
  end if;
  if p_feeling not in ('good','partial','difficult') then
    raise exception 'Ungültiges Startgefühl';
  end if;
  if p_icon not in ('target','ear','hand','clock','peace') then
    raise exception 'Ungültiges Zielsymbol';
  end if;
  if p_weekly_shell_target is not null
     and p_weekly_shell_target not between 1 and 200 then
    raise exception 'Muschelziel muss zwischen 1 und 200 liegen';
  end if;

  insert into public.weekly_plans(
    student_id,week_start,goal,goal_icon,help_text,checkin_feeling,
    checkin_completed,weekly_shell_target
  )
  values(
    p_student_id,p_week_start,btrim(p_goal),p_icon,coalesce(p_help_text,''),
    p_feeling,true,p_weekly_shell_target
  )
  on conflict(student_id,week_start)
  do update set
    goal=excluded.goal,
    goal_icon=excluded.goal_icon,
    help_text=excluded.help_text,
    checkin_feeling=excluded.checkin_feeling,
    checkin_completed=true,
    weekly_shell_target=excluded.weekly_shell_target,
    updated_at=now();
end;
$function$

CREATE OR REPLACE FUNCTION public.save_weekly_checkin(p_student_id uuid, p_week_start date, p_goal text, p_help_text text, p_feeling text, p_icon text, p_weekly_shell_target integer, p_reward_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_title text; v_school uuid; v_grade smallint; v_old public.weekly_plans%rowtype;
begin
 select c.school_id,c.grade_level into v_school,v_grade
 from public.students s join public.classes c on c.id=s.class_id
 where s.id=p_student_id and s.archived_at is null and c.archived_at is null;
 if auth.uid() is null or not (public.is_teacher_of_student(p_student_id) or
   (v_school is not null and v_grade is not null and public.has_grade_access(v_school,v_grade))) then
   raise exception 'Keine Berechtigung für dieses Kind';
 end if;
 if p_week_start is null or extract(isodow from p_week_start)<>1 then raise exception 'Ungültige Kalenderwoche'; end if;
 if btrim(coalesce(p_goal,''))='' then raise exception 'Wochenziel fehlt'; end if;
 if p_weekly_shell_target is null or p_weekly_shell_target not between 1 and 200 then raise exception 'Muschelziel muss zwischen 1 und 200 liegen'; end if;
 if p_feeling not in ('good','partial','difficult') or p_icon not in ('target','ear','hand','clock','peace') then raise exception 'Ungültige Auswahl'; end if;
 select title into v_title from public.rewards where id=p_reward_id and student_id=p_student_id and active=true;
 if v_title is null then raise exception 'Bitte eine aktive Belohnung dieses Kindes auswählen'; end if;
 select * into v_old from public.weekly_plans where student_id=p_student_id and week_start=p_week_start for update;
 if v_old.reward_redeemed_at is not null then raise exception 'Eingelöste Belohnung zuerst rückgängig machen'; end if;
 insert into public.weekly_plans(student_id,week_start,goal,help_text,checkin_feeling,goal_icon,checkin_completed,weekly_shell_target,reward_id,reward_title_snapshot)
 values(p_student_id,p_week_start,btrim(p_goal),coalesce(p_help_text,''),p_feeling,p_icon,true,p_weekly_shell_target,p_reward_id,v_title)
 on conflict(student_id,week_start) do update set goal=excluded.goal,help_text=excluded.help_text,
 checkin_feeling=excluded.checkin_feeling,goal_icon=excluded.goal_icon,checkin_completed=true,
 weekly_shell_target=excluded.weekly_shell_target,reward_id=excluded.reward_id,
 reward_title_snapshot=excluded.reward_title_snapshot,
 checkout_self=case when public.weekly_plans.weekly_shell_target is distinct from excluded.weekly_shell_target or public.weekly_plans.reward_id is distinct from excluded.reward_id then null else public.weekly_plans.checkout_self end,
 checkout_decision=case when public.weekly_plans.weekly_shell_target is distinct from excluded.weekly_shell_target or public.weekly_plans.reward_id is distinct from excluded.reward_id then null else public.weekly_plans.checkout_decision end,
 checkout_published=false;
end $function$

CREATE OR REPLACE FUNCTION public.legacy_reward_history(p_student_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_school uuid;v_grade smallint;
begin
 select c.school_id,c.grade_level into v_school,v_grade from public.students s join public.classes c on c.id=s.class_id where s.id=p_student_id;
 if auth.uid() is null or not(public.is_teacher_of_student(p_student_id) or (v_school is not null and v_grade is not null and public.has_grade_access(v_school,v_grade))) then raise exception 'Keine Berechtigung'; end if;
 return jsonb_build_object(
 'legacy_shells',coalesce((select shells from public.student_progress where student_id=p_student_id),0),
 'redemptions',coalesce((select jsonb_agg(jsonb_build_object('title',title,'shells_required',shells_required,'redeemed_at',redeemed_at) order by redeemed_at desc)
 from public.reward_redemptions where student_id=p_student_id),'[]'::jsonb));
end $function$

CREATE OR REPLACE FUNCTION public.set_weekly_reward_redemption(p_plan_id uuid, p_redeemed boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_plan public.weekly_plans%rowtype; v_school uuid; v_grade smallint; v_good integer;
begin
 select * into v_plan from public.weekly_plans where id=p_plan_id for update;
 if not found then raise exception 'Wochenplan nicht gefunden'; end if;
 select c.school_id,c.grade_level into v_school,v_grade
 from public.students s join public.classes c on c.id=s.class_id where s.id=v_plan.student_id and s.archived_at is null and c.archived_at is null;
 if auth.uid() is null or not (public.is_teacher_of_student(v_plan.student_id) or
   (v_school is not null and v_grade is not null and public.has_grade_access(v_school,v_grade))) then
   raise exception 'Keine Berechtigung';
 end if;
 if p_redeemed then
   if v_plan.reward_redeemed_at is not null then raise exception 'Belohnung bereits eingelöst'; end if;
   if v_plan.checkout_self is null then raise exception 'Bitte zuerst Check-out speichern'; end if;
   if not v_plan.checkin_completed or v_plan.weekly_shell_target is null or v_plan.reward_title_snapshot is null then raise exception 'Check-in fehlt'; end if;
   select count(*)::integer into v_good from public.ratings
   where student_id=v_plan.student_id and week_start=v_plan.week_start and rating='good';
   if v_good<v_plan.weekly_shell_target then raise exception 'Wochenziel noch nicht erreicht'; end if;
   update public.weekly_plans set reward_redeemed_at=now(),reward_redeemed_by=auth.uid(),
     published_good_count=v_good where id=p_plan_id;
 else
   if v_plan.reward_redeemed_at is null then raise exception 'Belohnung nicht eingelöst'; end if;
   update public.weekly_plans set reward_redeemed_at=null,reward_redeemed_by=null where id=p_plan_id;
 end if;
end $function$

CREATE OR REPLACE FUNCTION public.save_weekly_checkin_v2(p_student_id uuid, p_week_start date, p_goal text, p_help_text text, p_feeling text, p_icon text, p_weekly_shell_target integer, p_reward_template_id uuid, p_free_reward_title text, p_reward_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_title text;v_icon text;v_school uuid;v_grade smallint;v_old public.weekly_plans%rowtype;v_choices integer;
begin
 select c.school_id,c.grade_level into v_school,v_grade
 from public.students s join public.classes c on c.id=s.class_id
 where s.id=p_student_id and s.archived_at is null and c.archived_at is null;
 if auth.uid() is null or not(public.is_teacher_of_student(p_student_id) or
  (v_school is not null and v_grade is not null and public.has_grade_access(v_school,v_grade))) then raise exception 'Keine Berechtigung für dieses Kind'; end if;
 if p_week_start is null or extract(isodow from p_week_start)<>1 then raise exception 'Ungültige Kalenderwoche';end if;
 if btrim(coalesce(p_goal,''))='' then raise exception 'Wochenziel fehlt';end if;
 if p_weekly_shell_target is null or p_weekly_shell_target not between 1 and 200 then raise exception 'Muschelziel muss zwischen 1 und 200 liegen';end if;
 if p_feeling not in ('good','partial','difficult') or p_icon not in ('target','ear','hand','clock','peace') then raise exception 'Ungültige Auswahl';end if;
 v_choices=(p_reward_template_id is not null)::integer+(p_reward_id is not null)::integer+(nullif(btrim(coalesce(p_free_reward_title,'')),'') is not null)::integer;
 if v_choices<>1 then raise exception 'Bitte genau eine Belohnung auswählen';end if;
 if p_reward_template_id is not null then
   select title,icon_key into v_title,v_icon from public.reward_templates
   where id=p_reward_template_id and teacher_id=auth.uid() and archived_at is null;
 elsif p_reward_id is not null then
   select title,'gift' into v_title,v_icon from public.rewards
   where id=p_reward_id and student_id=p_student_id and active=true;
 else
   v_title=btrim(p_free_reward_title);v_icon='gift';
 end if;
 if v_title is null or length(v_title)<2 or length(v_title)>80 then raise exception 'Belohnung prüfen (2 bis 80 Zeichen)';end if;
 select * into v_old from public.weekly_plans where student_id=p_student_id and week_start=p_week_start for update;
 if v_old.reward_redeemed_at is not null then raise exception 'Eingelöste Belohnung zuerst rückgängig machen';end if;
 insert into public.weekly_plans(student_id,week_start,goal,help_text,checkin_feeling,goal_icon,checkin_completed,weekly_shell_target,reward_id,reward_template_id,reward_title_snapshot,reward_icon_snapshot)
 values(p_student_id,p_week_start,btrim(p_goal),coalesce(p_help_text,''),p_feeling,p_icon,true,p_weekly_shell_target,p_reward_id,p_reward_template_id,v_title,v_icon)
 on conflict(student_id,week_start) do update set goal=excluded.goal,help_text=excluded.help_text,checkin_feeling=excluded.checkin_feeling,
 goal_icon=excluded.goal_icon,checkin_completed=true,weekly_shell_target=excluded.weekly_shell_target,reward_id=excluded.reward_id,
 reward_template_id=excluded.reward_template_id,reward_title_snapshot=excluded.reward_title_snapshot,reward_icon_snapshot=excluded.reward_icon_snapshot,
 checkout_self=case when public.weekly_plans.weekly_shell_target is distinct from excluded.weekly_shell_target or
 public.weekly_plans.reward_title_snapshot is distinct from excluded.reward_title_snapshot then null else public.weekly_plans.checkout_self end,
 checkout_decision=case when public.weekly_plans.weekly_shell_target is distinct from excluded.weekly_shell_target or
 public.weekly_plans.reward_title_snapshot is distinct from excluded.reward_title_snapshot then null else public.weekly_plans.checkout_decision end,
 checkout_published=false;
end $function$

CREATE OR REPLACE FUNCTION public.save_weekly_checkin_v3(p_student_id uuid, p_week_start date, p_goal text, p_help_text text, p_feeling text, p_icon text, p_weekly_shell_target integer, p_reward_template_id uuid, p_free_reward_title text, p_reward_id uuid, p_save_as_template boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_title text;
begin
 perform public.save_weekly_checkin_v2(p_student_id,p_week_start,p_goal,p_help_text,p_feeling,p_icon,p_weekly_shell_target,
 p_reward_template_id,p_free_reward_title,p_reward_id);
 if coalesce(p_save_as_template,false) then
   if p_reward_template_id is not null or p_reward_id is not null then raise exception 'Nur eigene Belohnungen als Vorlage speichern';end if;
   v_title=btrim(p_free_reward_title);
   if not exists(select 1 from public.reward_templates where teacher_id=auth.uid() and title=v_title and archived_at is null) then
     insert into public.reward_templates(teacher_id,title,icon_key,shells_required) values(auth.uid(),v_title,'gift',1);
   end if;
 end if;
end $function$
